import json
import subprocess
import sys

from threetears.evals import Eval


def gloss(case):
    """Gloss one term through the command line, as the build does."""
    term = {"id": case["term_id"], "lang": case["lang"], "term": case["term"]}
    done = subprocess.run(
        [sys.executable, "glossator.py", "-", "-"], input=json.dumps(term), capture_output=True, text=True, check=True
    )
    return json.loads(done.stdout)


def headword_kept(case, out):
    """The headword is the term as the glossary prints it, accents and all."""
    return out["headword"] == case["headword"]


def slug_right(case, out):
    """The slug is the term's anchor."""
    return out["slug"] == case["slug"]


glossary = Eval("cases.jsonl", runner=gloss, grader=[headword_kept, slug_right], k=1)
